    "text": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Normandy 1944 Map Quiz</title>\n<style>body{margin:0;font-family:system-ui,sans-serif;background:#111;color:#eee;display:flex;flex-direction:column;align-items:center}canvas{background:#000;margin-top:12px}button{font:inherit;padding:8px 14px;margin:4px}</style>\n</head>\n<body>\n<h1>Normandy 1944 Map Quiz</h1>\n<p>A history quiz about the D-Day landings.</p>\n<p id=\"question\"></p>\n<div id=\"options\"></div>\n<p>Score: <span id=\"score\">0</span></p>\n<script>\nconst questions = [\n  {\n    \"question\": \"Which beach did the Canadian forces land on?\",\n    \"options\": [\n      \"Juno\",\n      \"Omaha\",\n      \"Utah\"\n    ],\n    \"answer\": 0\n  },\n  {\n    \"question\": \"What was the date of the landings?\",\n    \"options\": [\n      \"June 6, 1944\",\n      \"May 8, 1945\",\n      \"December 7, 1941\"\n    ],\n    \"answer\": 0\n  },\n  {\n    \"question\": \"Which flag flew over the Allied headquarters?\",\n    \"options\": [\n      \"Several: the US, UK and Canadian flags\",\n      \"Only one\",\n      \"None\"\n    ],\n    \"answer\": 0\n  }\n];\nlet index = 0, score = 0;\nfunction show() {\n  const current = questions[index % questions.length];\n  document.getElementById(\"question\").textContent = current.question;\n  const options = document.getElementById(\"options\");\n  options.innerHTML = \"\";\n  current.options.forEach((option, i) => {\n    const button = document.createElement(\"button\");\n    button.textContent = option;\n    button.onclick = () => { if (i === current.answer) score++; document.getElementById(\"score\").textContent = score; index++; show(); };\n    options.append(button);\n  });\n}\nshow();\n</script>\n</body>\n</html>\n"
