  "why": "An ordinary puzzle game with nothing in it that touches a rule.",
  "files": [
   {
    "path": "index.html",
    "text": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Slide Puzzle</title>\n<style>body{margin:0;font-family:system-ui,sans-serif;background:#111;color:#eee;display:flex;flex-direction:column;align-items:center}canvas{background:#000;margin-top:12px}button{font:inherit;padding:8px 14px;margin:4px}</style>\n</head>\n<body>\n<h1>Slide Puzzle</h1>\n<div id=\"board\" style=\"display:grid;grid-template-columns:repeat(3,64px);gap:4px\"></div>\n<script>\nlet tiles = [1, 2, 3, 4, 5, 6, 7, 8, 0];\nfor (let step = 0; step < 100; step++) { const blank = tiles.indexOf(0), moves = [blank - 3, blank + 3, blank - 1, blank + 1].filter((m) => m >= 0 && m < 9 && (Math.abs(m - blank) === 3 || Math.floor(m / 3) === Math.floor(blank / 3))); const pick = moves[Math.floor(Math.random() * moves.length)]; [tiles[blank], tiles[pick]] = [tiles[pick], tiles[blank]]; }\nfunction draw() {\n  const board = document.getElementById(\"board\"); board.innerHTML = \"\";\n  tiles.forEach((tile, i) => {\n    const button = document.createElement(\"button\");\n    button.textContent = tile || \"\"; button.style.height = \"64px\";\n    button.onclick = () => { const blank = tiles.indexOf(0); if (Math.abs(i - blank) === 3 || (Math.abs(i - blank) === 1 && Math.floor(i / 3) === Math.floor(blank / 3))) { [tiles[i], tiles[blank]] = [tiles[blank], tiles[i]]; draw(); } };\n    board.append(button);\n  });\n}\ndraw();\n</script>\n</body>\n</html>\n"
   }
  ]
