    "path": "index.html",
    "text": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>The Coin Collector</title>\n<style>body{margin:0;font-family:system-ui,sans-serif;background:#111;color:#eee;display:flex;flex-direction:column;align-items:center}canvas{background:#000;margin-top:12px}button{font:inherit;padding:8px 14px;margin:4px}</style>\n</head>\n<body>\n<h1>The Coin Collector</h1>\n<p id=\"scene\">Grandma keeps coins in jars. One jar holds a printout about Dogecoin that your cousin gave her as a joke.</p>\n<button id=\"next\">Open the next jar</button>\n<script>\nconst jars = [\"Old pennies from 1943.\", \"A foreign coin with a ship on it.\", \"A silver dollar nobody wants to spend.\"];\nlet index = 0;\ndocument.getElementById(\"next\").onclick = () => { document.getElementById(\"scene\").textContent = jars[index % jars.length]; index++; };\n</script>\n</body>\n</html>\n"
